namespace DualSpeaker {
 public partial class MainForm:Form {
  Settings settings;AudioEngine engine;ComboBox left,right,bus,mic,mode,latencyMode;Button start,stop,calibrate,test,refresh;NumericUpDown leftDelay,rightDelay;StudioValue leftGain,rightGain,masterVolume;Label masterVolumeText;Button masterMute;MediaVolumeKeys mediaKeys;VolumeOverlay volumeOverlay;NumericUpDown knobSensitivity;bool syncingMaster;StudioValue leftDeviceVolume,rightDeviceVolume;Label leftDeviceMute,rightDeviceMute;bool syncingVolume;Label status,meters,calibrationInfo;TextBox log;CheckBox autoCalibration;System.Windows.Forms.Timer timer;bool busy;bool autoStart,commission;int statusTicks;
  void Select(ComboBox box,DeviceChoice[] devices,string id){box.Items.Clear();box.Items.AddRange(devices);for(int i=0;i<devices.Length;i++)if(devices[i].Id==id){box.SelectedIndex=i;return;}if(devices.Length>0)box.SelectedIndex=0;}
  void RefreshDevices(){try{var ds=Devices.List(DataFlow.Render);var ms=Devices.List(DataFlow.Capture);Select(left,ds,settings.LeftId);Select(right,ds,settings.RightId);Select(bus,ds,settings.BusId);Select(mic,ms,settings.MicId);}catch(Exception ex){Append(ex.Message);}}
  void Save(){if(preview)return;try{Files.Save(Files.Config,settings);}catch(Exception ex){Append(ex.Message);}}
  void ApplySelections(){settings.LeftId=Selected(left);settings.RightId=Selected(right);settings.BusId=Selected(bus);settings.MicId=Selected(mic);settings.StereoSplit=mode.SelectedIndex==1;Save();}
  static string Selected(ComboBox b){var c=b.SelectedItem as DeviceChoice;if(c==null)throw new Exception("尚未选择音频设备。");return c.Id;}
  void PresentVolumeOverlay(){if(!settings.ShowVolumeOverlay||engine==null||!engine.Running)return;if(volumeOverlay==null||volumeOverlay.IsDisposed)volumeOverlay=new VolumeOverlay();volumeOverlay.Present((int)Math.Round(settings.MasterGain*100),settings.MasterMuted);}
  void RefreshMasterVolume(){((StudioReadout)masterVolumeText).Muted=settings.MasterMuted;masterVolumeText.Text=(settings.MasterGain*100).ToString("F0")+"%";masterMute.Text=settings.MasterMuted?"取消静音":"静音";((StudioButton)masterMute).Selected=settings.MasterMuted;masterMute.Invalidate();((StudioKnob)masterVolume).Muted=settings.MasterMuted;masterVolume.Invalidate();masterVolume.AccessibleDescription=settings.MasterMuted?"两路已静音":"两路总音量 "+masterVolumeText.Text;}
  void ApplyVolumeKey(int key){if(engine==null||!engine.Running)return;int percent=MediaVolumeKeys.AdjustVolume(settings,key);syncingMaster=true;try{masterVolume.Value=percent;}finally{syncingMaster=false;}RefreshMasterVolume();Save();PresentVolumeOverlay();}
  void ApplyMediaMute(bool muted){if(IsDisposed||!IsHandleCreated)return;if(InvokeRequired){BeginInvoke(new Action<bool>(ApplyMediaMute),muted);return;}if(engine==null||!engine.Running)return;settings.MasterMuted=muted;RefreshMasterVolume();Save();PresentVolumeOverlay();}
  void RefreshDeviceVolumes(){if(leftDeviceVolume==null||left==null||right==null)return;syncingVolume=true;try{ReadDeviceVolume(left,leftDeviceVolume,leftDeviceMute);ReadDeviceVolume(right,rightDeviceVolume,rightDeviceMute);}finally{syncingVolume=false;}}
  void ReadDeviceVolume(ComboBox choice,StudioValue control,Label muted){var d=choice.SelectedItem as DeviceChoice;if(d==null)return;try{using(var endpoint=Devices.Open(d.Id)){int percent=(int)Math.Round(endpoint.AudioEndpointVolume.MasterVolumeLevelScalar*100);if(!control.Capture)control.Value=Math.Max(0,Math.Min(100,percent));muted.Text=endpoint.AudioEndpointVolume.Mute?"已静音":"";}}catch{muted.Text="不可用";}}
  void SetDeviceVolume(bool isLeft){var label=isLeft?leftDeviceVolumeText:rightDeviceVolumeText;var slider=isLeft?leftDeviceVolume:rightDeviceVolume;if(label!=null)label.Text=slider.Value+"%";if(syncingVolume||preview)return;try{string id=Selected(isLeft?left:right);if(id==Selected(bus))throw new Exception("请选择蓝牙音响；内置声卡由静音保护管理。");var control=isLeft?leftDeviceVolume:rightDeviceVolume;using(var endpoint=Devices.Open(id)){endpoint.AudioEndpointVolume.MasterVolumeLevelScalar=(float)control.Value/100;endpoint.AudioEndpointVolume.Mute=control.Value==0;}if(!control.Capture)Append((isLeft?"左":"右")+"音响 Windows 设备音量设为 "+control.Value+"%。");}catch(Exception ex){Append("设备音量调整失败："+ex.Message);}RefreshDeviceVolumes();}
  void Append(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Append),text);return;}log.AppendText(DateTime.Now.ToString("HH:mm:ss")+" "+text+Environment.NewLine);}
  void Progress(string text){if(IsDisposed)return;BeginInvoke(new Action(()=>{status.Text=text;Append(text);}));}
  void EnableControls(){bool playing=engine!=null&&engine.Running;start.Enabled=!busy&&!playing;stop.Enabled=!busy&&playing;calibrate.Enabled=!busy&&playing;test.Enabled=!busy&&playing;refresh.Enabled=!busy&&!playing;left.Enabled=right.Enabled=bus.Enabled=mic.Enabled=latencyMode.Enabled=!busy&&!playing;leftDelay.Enabled=rightDelay.Enabled=leftGain.Enabled=rightGain.Enabled=mode.Enabled=autoCalibration.Enabled=leftDeviceVolume.Enabled=rightDeviceVolume.Enabled=!busy;}
  async Task StartPlayback(){if(busy)return;busy=true;EnableControls();try{ApplySelections();engine=new AudioEngine(settings);engine.MediaMuteRequested+=ApplyMediaMute;status.Text="正在打开两台音响…";await Task.Run(()=>engine.Start(true));status.Text="双音响正在播放电脑声音";Append("已启动。打开音乐或电影即可；播放器请选择默认输出。");}catch(Exception ex){Append("启动失败："+ex.Message);if(engine!=null){engine.Dispose();engine=null;}status.Text="启动失败";}finally{busy=false;EnableControls();}if(engine!=null&&engine.Running&&settings.CalibrateOnStart&&!Program.SkipCalibrationOnce)await AutoCalibrate();Program.SkipCalibrationOnce=false;}
  void StopPlayback(){if(volumeOverlay!=null)volumeOverlay.Dismiss();if(engine!=null){engine.Dispose();engine=null;Append("已停止并恢复系统音频设置。");}status.Text="已停止";EnableControls();}
  async Task AutoCalibrate(){if(busy||engine==null)return;busy=true;EnableControls();try{settings.MicId=Selected(mic);Append("正在短时录音校准。录音和测量结果保存在 diagnostics 文件夹。");var m=await Task.Run(()=>Calibration.Auto(engine,Progress));leftDelay.Value=(decimal)settings.LeftDelayMs;rightDelay.Value=(decimal)settings.RightDelayMs;Append("校准通过，复测残差 "+m.RightMinusLeftMs.ToString("F1")+" ms。");status.Text="校准完成，双音响正在播放";}catch(Exception ex){Append("校准未通过："+ex.Message);status.Text="播放继续；本轮校准未通过";}finally{busy=false;EnableControls();UpdateStatus();}}
  async Task TestPlayback(){if(busy||engine==null)return;busy=true;EnableControls();try{await Task.Run(()=>{engine.BeginDemo();try{Thread.Sleep(8500);}finally{engine.EndDemo();}});Append("8 秒验证音已播放，使用与电脑声音相同的分发缓冲。");}catch(Exception ex){Append(ex.Message);}finally{busy=false;EnableControls();}}
  async Task Commission(){busy=true;EnableControls();try{var measurements=await Task.Run(()=>{var list=new System.Collections.Generic.List<Measurement>();for(int i=0;i<3;i++){Progress("正在持续同步验证 "+(i+1)+"/3…");Thread.Sleep(3000);list.Add(Calibration.Measure(engine,"stability-"+i));}return list;});bool pass=settings.Calibrated&&measurements.All(m=>m.Valid&&Math.Abs(m.RightMinusLeftMs)<=25);var result=new{Time=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),Pass=pass,Scope="本次连接的短时声学复测；不代表长期绝对同步",Settings=settings,Measurements=measurements,InputFrames=engine.InputFrames,LeftFrames=engine.Left.FramesRead,RightFrames=engine.Right.FramesRead,LeftMissing=engine.Left.MissingFrames,RightMissing=engine.Right.MissingFrames};Files.Save(Path.Combine(Files.Root,"acceptance-report.json"),result);Files.Log("COMMISSION | pass="+pass+" | residuals="+String.Join(",",measurements.Select(m=>m.RightMinusLeftMs.ToString("F2")))+" | missing="+engine.Left.MissingFrames+","+engine.Right.MissingFrames);Append(pass?"短时持续同步验证通过。":"短时持续同步验证未通过，请查看验收报告。");status.Text=pass?"验证通过，正在播放电脑声音":"播放已启动；持续同步验证未通过";if(!pass){settings.Calibrated=false;settings.LastResidualMs=measurements.Last().RightMinusLeftMs;Save();}}catch(Exception ex){Files.Log("COMMISSION ERROR | "+ex);Append(ex.Message);}finally{busy=false;EnableControls();}}
  void UpdateStatus(){RefreshDeviceVolumes();calibrationInfo.Text=settings.Calibrated?"最近通过复测："+settings.CalibrationTime+"\n实测残差 "+settings.LastResidualMs.ToString("F1")+" ms · 本次测量值":"尚未保存通过复测的校准。\n移动音响或断线重连后，建议重新自动校准。";
   if(engine!=null&&engine.Running){if(++statusTicks%2==0)Files.Save(Path.Combine(Files.Root,"live-status.json"),new{Time=DateTime.Now.ToString("HH:mm:ss"),Running=engine.Running,MediaPlaybackActive=engine.MediaPlaybackActive,InputPeak=engine.InputPeak,LeftPeak=engine.Left.Peak,RightPeak=engine.Right.Peak,InputFrames=engine.InputFrames,LeftFrames=engine.Left.FramesRead,RightFrames=engine.Right.FramesRead,LeftMissing=engine.Left.MissingFrames,RightMissing=engine.Right.MissingFrames,Error=engine.Error,SpeakerMuted=engine.SpeakerMuted,MuteCorrections=engine.MuteCorrections,SourceBufferMs=settings.BufferMs,OutputBufferMs=settings.OutputBufferMs,LeftLagMs=engine.Left.LagMs,RightLagMs=engine.Right.LagMs,MasterVolumePercent=(int)Math.Round(settings.MasterGain*100),MasterMuted=settings.MasterMuted,VolumeStepPercent=settings.VolumeStepPercent,VolumeKeyEvents=mediaKeys==null?0:mediaKeys.HandledCommands});meters.Text=(engine.SpeakerMuted?"笔记本扬声器：静音保护已生效":"笔记本扬声器：正在检查静音")+" · 播放缓冲 "+settings.BufferMs+" ms\n实时电平：音源 "+engine.InputPeak.ToString("F3")+"   左 "+engine.Left.Peak.ToString("F3")+"   右 "+engine.Right.Peak.ToString("F3")+"\n缓冲缺帧计数：左 "+engine.Left.MissingFrames+"   右 "+engine.Right.MissingFrames;if(!String.IsNullOrEmpty(engine.Error)&&!busy){string error=engine.Error;StopPlayback();status.Text="设备或音源发生错误，已停止并恢复";Append(error);}}
   else meters.Text="点击开始播放后，可以在这里看到两路实时电平。";EnableControls();}
 }
 public class DemoMusic:ISampleProvider {long frame;public WaveFormat WaveFormat{get{return WaveFormat.CreateIeeeFloatWaveFormat(48000,2);}}public int Read(float[] b,int o,int c){double[] notes={261.63,329.63,392,523.25,440,392,329.63,261.63};for(int i=0;i<c/2;i++){double t=frame/48000.0,phase=t%1;int n=(int)t%notes.Length;double env=Math.Min(1,phase/.03)*Math.Max(0,1-phase);double a=t<8?.10*env*(Math.Sin(2*Math.PI*notes[n]*t)+.25*Math.Sin(2*Math.PI*notes[n]*2*t)):0;double z=t<8?.10*env*(Math.Sin(2*Math.PI*notes[(n+2)%notes.Length]*t)+.25*Math.Sin(2*Math.PI*notes[(n+2)%notes.Length]*2*t)):0;b[o+2*i]=(float)a;b[o+2*i+1]=(float)z;frame++;}return c;}}
 public static class Program {public static bool SkipCalibrationOnce;
  [STAThread]public static void Main(string[] args){HighDpi.Initialize();SkipCalibrationOnce=args.Contains("--skip-calibration");bool created;using(var mutex=new Mutex(true,"Local\\DualSpeakerAudioEngine",out created)){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(!created){MessageBox.Show("双音响程序已经在运行。","双蓝牙音响");return;}try{if(File.Exists(Files.Recovery))DefaultAudio.Recover();Process.Start(new ProcessStartInfo(Path.Combine(Files.Root,"DualSpeaker.Cli.exe"),"--watch "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true});Application.Run(new MainForm(args.Contains("--start")||args.Contains("--commission"),args.Contains("--commission")));}catch(Exception ex){Files.Log(ex.ToString());DefaultAudio.Recover();MessageBox.Show(ex.Message,"双音响启动失败");}}}
 }
}
